{
  "root_causes": [
    {
      "service": "attractions",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT time, metric, attr_k8s_pod_name AS pod, value FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'attractions%' AND metric IN ('k8s.container.ready','k8s.container.restarts') ORDER BY time, metric",
          "claim": "attractions pod stayed not-ready (ready=0) for the whole abnormal window while its restart count climbed from 4 to 6."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_pod_name AS pod, MIN(value) AS min_v, MAX(value) AS max_v FROM normal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'attractions%' GROUP BY 1,2,3",
          "claim": "In the normal period the attractions pod had zero restarts, so the restart count is new in the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, COUNT(*) AS n FROM abnormal_traces WHERE service_name='attractions' GROUP BY 1,2",
          "claim": "attractions emits no spans at all in the abnormal period, though normal has 391 server spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.span_name AS downstream_call, c.attr_status_code AS downstream_status, COUNT(*) AS n_calls, SUM(CASE WHEN s.attr_http_response_status_code=500 THEN 1 ELSE 0 END) AS frontend_500s FROM abnormal_traces c JOIN abnormal_traces s ON c.parent_span_id = s.span_id AND c.trace_id = s.trace_id WHERE c.service_name='frontend' AND c.attr_span_kind='Client' AND c.span_name LIKE 'attractions.%' GROUP BY 1,2 ORDER BY 3 DESC",
          "claim": "All 134 frontend calls to attractions fail in about 0.02 ms, and each maps to a frontend HTTP 500 on /museums, /restaurants, /cinema."
        }
      ]
